var mode='enc',tabs=document.getElementById('tabs');
tabs.addEventListener('click',function(e){
  var b=e.target.closest('button');if(!b)return;
  [].forEach.call(tabs.querySelectorAll('button'),function(x){x.classList.remove('active');});
  b.classList.add('active');mode=b.getAttribute('data-m');run();
});
function run(){
  var v=document.getElementById('in').value,f=document.getElementById('fn').value,out='',note='';
  if(!v){document.getElementById('out').value='';document.getElementById('note').textContent='Type or paste something and press Convert.';return;}
  try{
    if(mode==='enc'){out=f==='full'?encodeURI(v):encodeURIComponent(v);note='Encoded '+v.length+' characters into '+out.length+'.';}
    else{out=f==='full'?decodeURI(v):decodeURIComponent(v);note='Decoded successfully.';}
  }catch(err){
    out='';note='That input could not be decoded. Check for a stray % sign, which must be written as %25.';
  }
  document.getElementById('out').value=out;
  document.getElementById('note').textContent=note;
  WT.resize();
}
document.getElementById('go').addEventListener('click',run);
document.getElementById('in').addEventListener('input',run);
document.getElementById('fn').addEventListener('change',run);
document.getElementById('copy').addEventListener('click',function(){
  var ok=WT.copy(document.getElementById('out').value);
  document.getElementById('note').textContent=ok?'Copied to clipboard.':'Copy failed, select the text instead.';
});
document.getElementById('swap').addEventListener('click',function(){
  document.getElementById('in').value=document.getElementById('out').value;run();
});
